"""Provide the owned CODE-EVAL-002 suffix_mask fixture."""

import logging

logger = logging.getLogger(__name__)


def suffix_mask(value, visible):
    """Mask the entire string unless the visible suffix is strictly between zero and its length."""
    logger.info("ce002_fixture_called function=suffix_mask")
    if visible <= 0 or visible >= len(value):
        return "*" * len(value)
    return "*" * (len(value) - visible) + value[-visible:]

"""Provide the owned CODE-EVAL-002 prefix_mask fixture."""

import logging

logger = logging.getLogger(__name__)


def prefix_mask(value, visible):
    """Reveal only a strictly positive proper prefix; otherwise mask every character."""
    logger.info("ce002_fixture_called function=prefix_mask")
    if visible <= 0 or visible >= len(value):
        return "*" * len(value)
    return value[:visible] + "*" * (len(value) - visible)

"""Provide the owned CODE-EVAL-002 bounded_index fixture."""

import logging

logger = logging.getLogger(__name__)


def bounded_index(index, size):
    """Clamp an index into zero through size minus one; nonpositive sizes raise ValueError."""
    logger.info("ce002_fixture_called function=bounded_index")
    if size <= 0:
        raise ValueError("empty range")
    return max(0, min(index, size - 1))
